            'cookie_name=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJtZXNzYWdlIjoiaGVsbG8gd29ybGQifQ.B54pAqIiLbu170tGQ1rY06Twv__0qSHTA0ioQPIOvFE.i2NSvtJOXOPS9NDL1u8dqTYmMrzcD4mNSws6P6qmeV0%3D; Path=/',
        }),
      })
      const res = await app.request(req)
      expect(res).not.toBeNull()
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ message: 'hello world' })
      expect(handlerExecuted).toBeTruthy()
    })
  })

  describe('Credentials in cookie object with prefix Options', () => {
    let handlerExecuted: boolean

    beforeEach(() => {
      handlerExecuted = false
    })

    const app = new Hono()

    app.use(
      '/auth/*',
      jwt({
        secret: 'a-secret',
        alg: 'HS256',
        cookie: {
          key: 'cookie_name',
          prefixOptions: 'host',
        },
      })
    )

    app.get('/auth/*', async (c) => {
      handlerExecuted = true
      const payload = c.get('jwtPayload')
      return c.json(payload)
    })

    it('Should not authorize', async () => {
      const req = new Request('http://localhost/auth/a')
      const res = await app.request(req)
      expect(res).not.toBeNull()
      expect(res.status).toBe(401)
      expect(await res.text()).toBe('Unauthorized')
      expect(handlerExecuted).toBeFalsy()
    })

    it('Should authorize', async () => {
      const url = 'http://localhost/auth/a'
      const req = new Request(url, {
        headers: new Headers({
          Cookie:
            '__Host-cookie_name=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJtZXNzYWdlIjoiaGVsbG8gd29ybGQifQ.B54pAqIiLbu170tGQ1rY06Twv__0qSHTA0ioQPIOvFE',
        }),
      })
      const res = await app.request(req)
      expect(res).not.toBeNull()
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ message: 'hello world' })
      expect(handlerExecuted).toBeTruthy()
    })
  })

  describe('Credentials in cookie object without prefix Options', () => {
    let handlerExecuted: boolean

    beforeEach(() => {
      handlerExecuted = false
    })

    const app = new Hono()

    app.use(
      '/auth/*',
      jwt({
        secret: 'a-secret',
        alg: 'HS256',
        cookie: {
          key: 'cookie_name',
        },
      })
    )

    app.get('/auth/*', async (c) => {
      handlerExecuted = true
      const payload = c.get('jwtPayload')
      return c.json(payload)
    })

    it('Should not authorize', async () => {
      const req = new Request('http://localhost/auth/a')
      const res = await app.request(req)
      expect(res).not.toBeNull()
      expect(res.status).toBe(401)
      expect(await res.text()).toBe('Unauthorized')
      expect(handlerExecuted).toBeFalsy()
    })

    it('Should authorize', async () => {
      const url = 'http://localhost/auth/a'
      const req = new Request(url, {
        headers: new Headers({
          Cookie:
            'cookie_name=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJtZXNzYWdlIjoiaGVsbG8gd29ybGQifQ.B54pAqIiLbu170tGQ1rY06Twv__0qSHTA0ioQPIOvFE',
        }),
      })
      const res = await app.request(req)
      expect(res).not.toBeNull()
      expect(res.status).toBe(200)
      expect(await res.json()).toEqual({ message: 'hello world' })
      expect(handlerExecuted).toBeTruthy()
    })
  })

  describe('Security: Algorithm Confusion Attack Prevention', () => {
    it('Should throw error when alg option is not provided', () => {
      expect(() => {
        // @ts-expect-error - intentionally testing without alg option
        jwt({ secret: 'a-secret' })
      }).toThrow('JWT auth middleware requires options for "alg"')
    })

    it('Should reject tokens with mismatched algorithm', async () => {
      const app = new Hono()

      // Configure middleware to expect RS256
      app.use('/auth/*', jwt({ secret: 'a-secret', alg: 'RS256' }))
      app.get('/auth/*', (c) => {
        return c.json(c.get('jwtPayload'))
      })

      // Try to use a HS256 token (algorithm confusion attempt)
      const hs256Token =
        'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJtZXNzYWdlIjoiaGVsbG8gd29ybGQifQ.B54pAqIiLbu170tGQ1rY06Twv__0qSHTA0ioQPIOvFE'

      const req = new Request('http://localhost/auth/a')
      req.headers.set('Authorization', `Bearer ${hs256Token}`)
      const res = await app.request(req)

      // Should fail because the token algorithm doesn't match expected algorithm
      expect(res.status).toBe(401)
    })

    it('Should require explicit alg specification in middleware options', () => {
      // This should work - explicit alg specified
      expect(() => {
        jwt({ secret: 'a-secret', alg: 'HS256' })
      }).not.toThrow()

      // This should throw - alg not specified
      expect(() => {
        // @ts-expect-error - intentionally testing without alg option
        jwt({ secret: 'a-secret' })
      }).toThrow('JWT auth middleware requires options for "alg"')
    })
  })

  describe('Type tests', () => {
    it('Should infer correct payload type when JwtVariables<T> is specified', () => {
      type User = {
        id: string
        email: string
        isAdmin: boolean
      }

      const app = new Hono<{ Variables: JwtVariables<User> }>()

      app.get('/', (c) => {
        const payload = c.var.jwtPayload
        expectTypeOf(payload).toEqualTypeOf<User>()
        return c.json(payload)
      })
    })

    it('Should infer unknown when JwtVariables is used without type parameter in Variables', () => {
      const app = new Hono<{ Variables: JwtVariables }>()

      app.get('/', (c) => {
        const payload = c.var.jwtPayload
        expectTypeOf(payload).toEqualTypeOf<any>()
        return c.json(payload)
      })
    })
  })
})

