282	  const parts = token.split('.')
283	  if (parts.length !== 3) {
284	    throw new JwtTokenInvalid(token)
285	  }
286	  try {
287	    return decodeJwtPart(parts[0]) as TokenHeader
288	  } catch {
289	    throw new JwtTokenInvalid(token)
