/**
 * JWT Refresh Token Middleware for Hono.
 *
 * Verifies an access token (read from the `Authorization` header). If the access
 * token is expired but a valid refresh token is present (read from a cookie),
 * a new access token is issued via the `onRefresh` callback and exposed to the
 * client through a response header.
 *
 * @param {object} options - The options for the JWT refresh middleware.
 * @param {SignatureKey} options.secret - The secret used to verify the access token.
 * @param {SignatureAlgorithm} options.alg - Signature algorithm used for both tokens.
 * @param {SignatureKey} [options.refreshSecret] - Secret used to verify the refresh token. Defaults to `options.secret`.
 * @param {string} [options.refreshCookie='refresh_token'] - Cookie name carrying the refresh token.
 * @param {string} [options.headerName='Authorization'] - Request header carrying the access token.
 * @param {string} [options.newAccessTokenHeader='X-Access-Token'] - Response header used to deliver a freshly issued access token.
 * @param {VerifyOptions} [options.verification] - Additional options passed to `Jwt.verify`.
 * @param {(payload: unknown) => Promise<string>} options.onRefresh - Callback that produces a new access token from the verified refresh-token payload.
 * @returns {MiddlewareHandler} The middleware handler function.
 */
export const jwtRefresh = (options: {
  secret: SignatureKey
  alg: SignatureAlgorithm
  refreshSecret?: SignatureKey
  refreshCookie?: string
  headerName?: string
  newAccessTokenHeader?: string
  verification?: VerifyOptions
  onRefresh: (payload: unknown) => Promise<string>
}): MiddlewareHandler => {
  if (!options || !options.secret) {
    throw new Error('JWT refresh middleware requires options for "secret"')
  }

  if (!options.alg) {
    throw new Error('JWT refresh middleware requires options for "alg"')
  }

  if (typeof options.onRefresh !== 'function') {
    throw new Error('JWT refresh middleware requires options for "onRefresh"')
  }

  if (!crypto.subtle || !crypto.subtle.importKey) {
    throw new Error('`crypto.subtle.importKey` is undefined. JWT refresh middleware requires it.')
  }

  const verifyOpts = options.verification || {}
  const refresh[REDACTED] ?? options.secret
  const refreshCookieName = options.refreshCookie || 'refresh_token'
  const newAccessTokenHeader = options.newAccessTokenHeader || 'X-Access-Token'

  return async function jwtRefresh(ctx, next) {
    const headerName = options.headerName || 'Authorization'
    const credentials = ctx.req.raw.headers.get(headerName)

    let accessToken: string | undefined
    if (credentials) {
      const parts = credentials.split(/\s+/)
      if (parts.length !== 2 || parts[0].toLowerCase() !== 'bearer') {
        const errDescription = 'invalid credentials structure'
        throw new HTTPException(401, {
          message: errDescription,
          res: unauthorizedResponse({
            ctx,
            error: 'invalid_request',
            errDescription,
          }),
        })
      }
      accessToken = parts[1]
    }

    let accessPayload
    let accessError: unknown
    if (accessToken) {
      try {
        accessPayload = await Jwt.verify(accessToken, options.secret, {
          alg: options.alg,
          ...verifyOpts,
        })
      } catch (e) {
        accessError = e
      }
    }

    if (accessPayload) {
      ctx.set('jwtPayload', accessPayload)
      await next()
      return
    }

    const refreshToken = getCookie(ctx, refreshCookieName)

    if (!refreshToken) {
      const errDescription = accessToken
        ? 'token verification failure'
        : 'no authorization included in request'
      throw new HTTPException(401, {
        message: accessToken ? 'Unauthorized' : errDescription,
        res: unauthorizedResponse({
          ctx,
          error: accessToken ? 'invalid_token' : 'invalid_request',
          statusText: accessToken ? 'Unauthorized' : undefined,
          errDescription,
        }),
        cause: accessError,
      })
    }

    let refreshPayload
    let refreshError: unknown
    try {
      refreshPayload = await Jwt.verify(refreshToken, refreshSecret, {
        alg: options.alg,
        ...verifyOpts,
      })
    } catch (e) {
      refreshError = e
    }

    if (!refreshPayload) {
      throw new HTTPException(401, {
        message: 'Unauthorized',
        res: unauthorizedResponse({
          ctx,
          error: 'invalid_token',
          statusText: 'Unauthorized',
          errDescription: 'refresh token verification failure',
        }),
        cause: refreshError,
      })
    }

    const newAccessToken = await options.onRefresh(refreshPayload)
    const { payload: newPayload } = Jwt.decode(newAccessToken)

    ctx.set('jwtPayload', newPayload)
    await next()
    ctx.res.headers.set(newAccessTokenHeader, newAccessToken)
  }
}

export const verifyWithJwks = Jwt.verifyWithJwks
export const verify = Jwt.verify
export const decode = Jwt.decode
export const sign = Jwt.sign

