      })
    })
  })

  describe('Refresh token middleware', () => {
    const accessSecret = 'access-secret'
    const refreshSecret = 'refresh-secret'
    const now = Math.floor(Date.now() / 1000)

    const buildApp = (opts?: { refreshSecret?: string; refreshCookie?: string }) => {
      const app = new Hono()
      let issued = 0
      app.use(
        '/auth/*',
        jwtRefresh({
          secret: accessSecret,
          alg: 'HS256',
          refreshSecret: opts?.refreshSecret ?? refreshSecret,
          refreshCookie: opts?.refreshCookie,
          onRefresh: async (payload) => {
            issued++
            const p = payload as { sub?: string }
            return await sign(
              { sub: p.sub ?? 'unknown', exp: now + 3600, iat: now, refreshed: true },
              accessSecret,
              'HS256'
            )
          },
        })
      )
      app.get('/auth/me', (c) => {
        const payload = c.get('jwtPayload')
        return c.json({ payload, issued })
      })
      return app
    }

    it('Should reject when neither access nor refresh tokens are present', async () => {
      const app = buildApp()
      const res = await app.request('http://localhost/auth/me')
      expect(res.status).toBe(401)
      expect(res.headers.get('www-authenticate')).toContain(
        'error_description="no authorization included in request"'
      )
    })

    it('Should authorize and proceed normally with a valid access token', async () => {
      const app = buildApp()
      const accessToken = await sign({ sub: 'alice', exp: now + 3600 }, accessSecret, 'HS256')
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${accessToken}`)
      const res = await app.request(req)
      expect(res.status).toBe(200)
      const body = (await res.json()) as { payload: { sub: string }; issued: number }
      expect(body.payload.sub).toBe('alice')
      expect(body.issued).toBe(0)
      expect(res.headers.get('X-Access-Token')).toBeNull()
    })

    it('Should refresh when access token is expired but refresh token is valid', async () => {
      const app = buildApp()
      const expiredAccess = await sign(
        { sub: 'alice', exp: now - 60, iat: now - 3600 },
        accessSecret,
        'HS256'
      )
      const validRefresh = await sign(
        { sub: 'alice', exp: now + 86400, iat: now },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${expiredAccess}`)
      req.headers.set('Cookie', `refresh_token=${validRefresh}`)
      const res = await app.request(req)
      expect(res.status).toBe(200)
      const newAccess = res.headers.get('X-Access-Token')
      expect(newAccess).toBeTruthy()

      const verified = await Jwt.verify(newAccess as string, accessSecret, 'HS256')
      expect(verified.sub).toBe('alice')
      expect(verified.refreshed).toBe(true)

      const body = (await res.json()) as { payload: { sub: string; refreshed: boolean }; issued: number }
      expect(body.payload.sub).toBe('alice')
      expect(body.payload.refreshed).toBe(true)
      expect(body.issued).toBe(1)
    })

    it('Should reject when both access token and refresh token are invalid', async () => {
      const app = buildApp()
      const expiredAccess = await sign(
        { sub: 'alice', exp: now - 60, iat: now - 3600 },
        accessSecret,
        'HS256'
      )
      const expiredRefresh = await sign(
        { sub: 'alice', exp: now - 60, iat: now - 3600 },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${expiredAccess}`)
      req.headers.set('Cookie', `refresh_token=${expiredRefresh}`)
      const res = await app.request(req)
      expect(res.status).toBe(401)
      expect(res.headers.get('www-authenticate')).toContain(
        'error_description="refresh token verification failure"'
      )
    })

    it('Should reject when access token is expired and no refresh cookie is sent', async () => {
      const app = buildApp()
      const expiredAccess = await sign(
        { sub: 'alice', exp: now - 60, iat: now - 3600 },
        accessSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${expiredAccess}`)
      const res = await app.request(req)
      expect(res.status).toBe(401)
      expect(res.headers.get('www-authenticate')).toContain(
        'error_description="token verification failure"'
      )
    })

    it('Should use the configured refresh cookie name', async () => {
      const app = buildApp({ refreshCookie: 'rt' })
      const expiredAccess = await sign(
        { sub: 'bob', exp: now - 60, iat: now - 3600 },
        accessSecret,
        'HS256'
      )
      const validRefresh = await sign(
        { sub: 'bob', exp: now + 86400, iat: now },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${expiredAccess}`)
      req.headers.set('Cookie', `rt=${validRefresh}`)
      const res = await app.request(req)
      expect(res.status).toBe(200)
      expect(res.headers.get('X-Access-Token')).toBeTruthy()
    })

    it('Should default refreshSecret to the access secret when not provided', async () => {
      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
          secret: accessSecret,
          alg: 'HS256',
          onRefresh: async () =>
            await sign({ sub: 'carol', exp: now + 3600 }, accessSecret, 'HS256'),
        })
      )
      app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

      const expiredAccess = await sign(
        { sub: 'carol', exp: now - 60, iat: now - 3600 },
        accessSecret,
        'HS256'
      )
      const validRefreshSignedWithAccess = await sign(
        { sub: 'carol', exp: now + 86400, iat: now },
        accessSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${expiredAccess}`)
      req.headers.set('Cookie', `refresh_token=${validRefreshSignedWithAccess}`)
      const res = await app.request(req)
      expect(res.status).toBe(200)
      expect(res.headers.get('X-Access-Token')).toBeTruthy()
    })

    it('Should reject malformed Authorization header without consulting refresh token', async () => {
      const app = buildApp()
      const validRefresh = await sign(
        { sub: 'alice', exp: now + 86400, iat: now },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', 'NotBearer token')
      req.headers.set('Cookie', `refresh_token=${validRefresh}`)
      const res = await app.request(req)
      expect(res.status).toBe(401)
      expect(res.headers.get('www-authenticate')).toContain(
        'error_description="invalid credentials structure"'
      )
    })

    it('Should throw configuration errors for missing required options', () => {
      expect(() => {
        // @ts-expect-error - missing secret
        jwtRefresh({ alg: 'HS256', onRefresh: async () => '' })
      }).toThrow('JWT refresh middleware requires options for "secret"')

      expect(() => {
        // @ts-expect-error - missing alg
        jwtRefresh({ secret: 'x', onRefresh: async () => '' })
      }).toThrow('JWT refresh middleware requires options for "alg"')

      expect(() => {
        // @ts-expect-error - missing onRefresh
        jwtRefresh({ secret: 'x', alg: 'HS256' })
      }).toThrow('JWT refresh middleware requires options for "onRefresh"')
    })

    it('Should surface HTTPException with cause when refresh token is malformed', async () => {
      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
          secret: accessSecret,
          alg: 'HS256',
          refreshSecret,
          onRefresh: async () =>
            await sign({ sub: 'alice', exp: now + 3600 }, accessSecret, 'HS256'),
        })
      )
      app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))
      app.onError((e, c) => {
        if (e instanceof HTTPException && e.cause instanceof Error) {
          return c.json({ name: e.cause.name }, 401)
        }
        return c.text('err', 401)
      })

      const expiredAccess = await sign(
        { sub: 'alice', exp: now - 60, iat: now - 3600 },
        accessSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${expiredAccess}`)
      req.headers.set('Cookie', 'refresh_token=not.a.jwt')
      const res = await app.request(req)
      expect(res.status).toBe(401)
      const body = (await res.json()) as { name: string }
      expect(body.name).toBeTruthy()
    })
  })
})

